(()=>{const A='#ff86c2',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fxbar i{display:block;height:100%;width:0;background:${A};box-shadow:0 0 15px ${A}}.fxg{position:fixed;z-index:1;pointer-events:none;width:280px;height:280px;border-radius:50%;transform:translate(-50%,-50%);background:radial-gradient(circle,${A}20,transparent 68%);filter:blur(7px)}.fxo{position:fixed;z-index:-1;pointer-events:none;border-radius:50%;filter:blur(80px);opacity:.12}.fxo.a{width:340px;height:340px;left:-120px;top:20%;background:${A};animation:drift 13s ease-in-out infinite}.fxo.b{width:360px;height:360px;right:-150px;bottom:5%;background:#8d5bff;animation:drift 17s ease-in-out infinite reverse}.fxr{opacity:0;transform:translateY(38px) scale(.985);transition:1s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}.fxt{transform-style:preserve-3d;transition:transform .3s ease,box-shadow .3s ease}@keyframes drift{50%{transform:translate(80px,-45px)}}@media(max-width:700px){.fxg{display:none}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);['a','b'].forEach(c=>{const o=document.createElement('div');o.className='fxo '+c;b.appendChild(o)});const g=document.createElement('div');g.className='fxg';b.appendChild(g);if(!reduce)addEventListener('pointermove',e=>{g.style.left=e.clientX+'px';g.style.top=e.clientY+'px'});document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));if(!reduce)document.querySelectorAll('.cards article,.memory,.envelope,.pill,.quote').forEach(c=>{c.classList.add('fxt');c.addEventListener('pointermove',e=>{const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;c.style.transform=`perspective(700px) rotateX(${y*-5}deg) rotateY(${x*5}deg) translateY(-5px)`});c.addEventListener('pointerleave',()=>c.style.transform='')});addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();